import{_ as p,c as e,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"損","description":"高島易斷 - 損","frontmatter":{"title":"損","description":"高島易斷 - 損"},"headers":[],"relativePath":"classics/takashima/041.md","filePath":"classics/takashima/041.md"}'),i={name:"classics/takashima/041.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="損" tabindex="-1">損 <a class="header-anchor" href="#損" aria-label="Permalink to “損”">​</a></h1><h2 id="損-1" tabindex="-1">損 <a class="header-anchor" href="#損-1" aria-label="Permalink to “損”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>損：有孚，元吉，無咎，可貞。利有攸往，曷之用，二簋可用享。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>“損”通鹹，有心為感，無心為鹹。鹹，感孚也，故曰“有孚”，以其所損者，出於中心之誠，有足以見信於人也。不然，《損》主節儉，而儉不中禮，卒來譏刺，咎且難免，奚見“元吉”乎？惟損而“有孚”，斯人感其誠，自得“元吉”，復何咎？而可正，以斯而往，無往不利也。《損》儉如此，何用豐為乎？約之“二簋”，亦可“用享”，不特有孚於人，且可上孚夫神明矣。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>山下有澤，損。君子以懲忿窒欲。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>地以益而成山，即以損而成澤。山澤本損益之物，不益則山必崩，不損則澤必涸，此卦之所以名《損》也。在人之易發而難制者，無如忿，易熾而難絕者，無如欲。君子見此象，知怒氣之盛，勢足拔山，故必懲之，以遏剛強之性；貪念之深，盈難填壑，故必窒之，以塞利竇之源。怒起於剛，“懲忿”以息其既往；貪牽於情，“窒慾”以閒其將來。《艮》山止而《兌》澤塞，皆有《損》之象焉。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：目下行運不正，宜自懲忿。</p><p>○　問營商：營商原在謀財，宜和氣，不宜恃氣，宜審利，不宜放利。</p><p>○　問功名：忿欲不除，雖有功名，恐不能保其終也。</p><p>○　問戰徵：“山下有澤”，防山下深處，有敵兵埋伏。</p><p>○　問婚姻：卦自《鹹》《恆》來，女悅而男止，夫婦之道，得其正也。</p><p>○　問家宅：此宅後有高山，前有深澤，地勢頗險，宜開鑿之使平。</p><p>○　問訟事：不使氣，不貪財，訟自平矣。</p><p>○　問失物：不得。</p><p>○　問六甲：單月生男，雙月生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初爻處卦之始，即為謀事之始也。“已事”者，已其事也，即《艮》止之意；“遄往”者，遄，速也。事既可已，即當“遄往”，一經因循，必致誤事，是以有咎，故曰“已事遄往，無咎”。若事在可已不可已之間，已之則失業，不已則害公，惟當酌其輕重緩急之宜，故曰“酌損之”。《象傳》以“尚合志”釋之，“尚”作上，庶幾也，“已事遄往”，庶幾與上合志也。虞氏以“已”作祀，謂祭祀，祀事而云“酌損”，即《彖》所云“二簋可用享”之義。其說亦通。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：已往莫追，目下宜急加勉，自可免咎。</p><p>○　問戰徵：宜速進兵，不可遲緩，輜重糧食，亦須“酌損”。</p><p>○　問營商：販運宜速，審時度勢，宜酌量前行，定可獲利，必無咎也。</p><p>○　問功名：速往則得，遲緩無成。</p><p>○　問婚姻：即日迎娶，兩姓好合。</p><p>○　問家宅：須速他遷，吉。</p><p>○　問訟事：即速了結罷訟。</p><p>○　問失物：速尋可得。</p><p>○　問六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>友人某來曰：有朋友以急需借金，請佔後日利害。筮得《損》之《蒙》。</p><p>斷曰：爻居內卦，又在初位，內卦為《兌》，《兌》為口，有開口求人之象。爻辭曰“已事遄往，無咎”，謂當此時處困難，宜拋棄其事，趕急前往，以求救援，得季布之千金一諾，斯可無咎矣。“酌損之”者，謂其所借金數，或有不足，又宜酌量多寡，以賑其乏。玩此爻辭，知需用急切，有不可片刻寬緩者，緩即有咎；但所借之款，必有減少，亦不至空手而回也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>二處內卦之中，凡事之有待損之益之者，必其未協於中也，二得中，則以“弗損”為“利貞”。若不可損而損之，則損之反失中，是以“徵兇”。《損》與《益》相對，人只知損其所《損》，以損為益，不知不損其所不損，不損乃為《益》。蓋其所弗損弗益者，惟在守其中道而已，得其中，即“利貞”也。《象傳》以“中以為志”釋之，志，猶射之的，以中為的，志之於此也。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：好運方來，不減不加，萬事得中，自然獲利。</p><p>○　問戰徵：不必減糧，不必添兵，堅守中營，有勝無敗；若魯莽前往，恐有兇也。</p><p>○　問營商：貨物合宜，不必減價，無不獲利。</p><p>○　問功名：無榮無辱，青氈守舊。</p><p>○　問婚姻：兩姓門戶相當，吉。</p><p>○　問家宅：地位得中，不必添改，大利。</p><p>○　問訟事：平和。</p><p>○　問失物：原物無失。</p><p>○　問六甲：生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>友人某來曰：餘為家兄在大阪壟斷米市，大受虧耗，有獻斡旋之策者，以電報來告，催餘運送多金，猶得轉敗為勝。餘恐再失，則受虧愈大，因佔其成否如何？筮得《損》之《頤》。</p><p>斷曰：卦象澤低而山高，知一時米價，大有高下之勢。初次見價低，而多數約買，今臨期騰貴，不能不如數應付，以致受耗。東京支店之金，不可動也，謂之“利貞”，若送金而往，謂之“徵兇”。大阪本店雖虧，以東京支店維持之，自可挽回，謂之“弗損益之”。後果如所佔。</p><p>明治六年，貴顯某任某縣縣令，來請佔氣運，筮得《損》之《頤》。</p><p>斷曰：《損》卦為損下而益上，二爻曰“弗損益之”，是明明言下不必損，上不必益也。今足下出任某縣令，佔得此爻，爻辭曰：“九二：利貞，徵兇。弗損益之。”以九二爻位得正，宜固守成規，不必改作，自得其利。若妄自更張，競求進步，反致兇也，故無取於《損》，“弗損”即為“利貞”。足下其謹遵爻辭，行之可也。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>六三辰在亥，得乾氣，《乾》為人，又為行，三爻為三人，故曰“三人行”。《乾》上至三而變《兌》，是三損一也；上互《坤》，變《坤》之上畫成《艮》，二陰一陽，故曰“一人行”。三為《損》卦主爻，居《兌》卦之終，《兌》為友，故曰“得其友”，是《艮》得其友也。蓋天下事，一則不足，三則過之，以二為得中，乃奇偶之定數，是以“三人行”，則損其一以成二，一人行，則“得其友”亦成二。一而二，二而一，斯之為合志，不然，三人成眾，眾則人心不一，而疑惑生焉，故《象傳》以“三則疑也”釋之。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：財運平平，少則獲利，多則有損。利雙月，不利單月。</p><p>○　問戰徵：宜從兌方，一路進軍，自有援兵相助，有勝無敗。</p><p>○　問營商：商業宜於一人獨做，否則二人同辦，再多則必有損。</p><p>○　問功名：須一人獨往，必得成名。</p><p>○　問婚姻：得友，即得偶也，吉。</p><p>○　問家宅：宅在兌方，宅中丁口，每家只有兩丁可斷。</p><p>○　問訟事：兩造成訟，為中有一人唆弄所致，去此一人，則訟了矣。</p><p>○　問六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>明治二十五年四月，餘任北海道炭礦鐵道會社長之役，將赴所在，佔改正處分如何，筮得《損》之《大畜》。</p><p>斷曰：卦體《艮》山《兌》澤，卦德損下益上，明見上卦之山愈高，下卦之澤愈低，有上下不通之勢。上下不通，必致事務阻礙，弊端百出，會社因之招損失也。今餘恭任社長，勢不可不淘汰人員，革除敝害，然此社之弊有二：一系社務，不專關營利主義，一系社員，多由官吏而來；不關營利主義，則社用之出納無準，由官吏而來，則社規之約束難齊，於是耗費多，冗員眾，社中諸務，皆有名無實而已。餘欲振興會社，所以不能不銳意改革也。今佔得三爻，玩繹爻辭，是明明告我三分中損一之法也。餘得此卦，遂單身赴北海道，斷行改革，先減役員三分之一，開其端緒，自是而社務遂大得整頓。</p><p>明治二十五年，餘為北海道炭礦會社社長，時因石炭之販路有礙，所採掘石炭，堆聚不售，社員皆為焦心。筮得《損》之《大畜》。</p><p>斷曰：據爻辭稱“三人行，則損一人，一人行，則得友”，是明示以少則得利，多則有損，為目下之情形也。至四爻，則曰“損其疾，使遄有喜”，是明言去其貨之劣者，使往售而有喜也。五爻則曰“或益之十朋之龜，弗克違，元吉”，按古者貨貝五朋，是明言必將益價，莫之能違，是以大吉；上爻則曰“弗損益之，利有攸往”，是明言價格上落，可以到處銷售，自能獲利也。此後出《損》入《益》，《益》《彖》曰“利有攸往，利涉大川”，是明言可以販運出洋，銷行於外國也。《益》六爻，皆有暢銷獲利之象，由此推之，以一爻為一年，洞悉九年如一日，集社員示以此斷。果哉！二十五年，多蓄石炭，二十六年販路頓開，照此佔辭，料知此後社務，必可隆昌也。</p><p>友人某來，請佔事業之成否，筮得《損》之《大畜》。</p><p>斷曰：此卦山高而上聳，澤低而下陷，山澤不通氣，有草木不生，魚龜不育之象。今佔得三爻，爻辭大旨，謂三人則損，一人則得，知合眾興事，必多意見不合，反致損失。足下能獨力成事，必得同心之友來助，可以興業而有為也。</p><p>明治三十二年一月，自由黨與政府提攜議會，所議漸合政府之意，自由黨乃推選三人，請置大臣之位，政府不允，諸新聞多論其可否。某議員來，請佔自由黨之意向，果否貫徹，筮得《損》之《大畜》。</p><p>斷曰：此卦外卦為政府，內卦為黨員，黨員向政府推舉大臣，政府秉《艮》止之性，不允其請，是下悅上止，故名其卦曰《損》。六三陰爻，與上九陽爻相應，故黨員之意，得達政府，在政府為今進黨員三人，不得不點大臣三人，是政府之所以為難也。或三人中選用二人乎？謂之“三人行，則損一人”；或只用一人乎？謂之“一人行，則得其友”也。他日偶晤板垣伯，談及此佔，相與一笑。後因黨內有猜忌者，此事遂止。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>此爻以陰居陰，為外卦之始，與初九相應，初動體《坎》，《坎》為心病，疾所由生。疾曰“其疾”，“其”指初也，得四為之應，內外皆知所當損，而決計損之，則事之《損》猶在後，疾之《損》為在先也。疾《損》而“遄”，“遄”者初，使之遄者，四也。蓋有疾則憂，疾《損》則喜，故“無咎”也。《象傳》以“亦可喜”釋之，謂不必言《損》事，但言《損》疾，而亦可喜，則《損》事之喜，更可知矣。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：目下雖有小災，得救即療，可以轉憂為喜。</p><p>○　問營商：貨宜減辦，使之即往販售，獲利可喜。</p><p>○　問戰徵：未免遭傷，醫治可療，無咎。</p><p>○　問家宅：此宅陰氣過盛，宅眷致多疾病，祈禱可療，無咎。</p><p>○　問功名：一時難望。</p><p>○　問婚姻：四與初相應，初陽四陰，陰陽相合，必成可喜。</p><p>○　問訟事：“疾”者，害也，去其所害，訟自平矣。</p><p>○　問行人：有事他往，一時未歸，有喜無咎。</p><p>○　問六甲：生男。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>工部省書記杉實信氏，予舊親也。明治十五年二月某日晨起得電報，雲杉氏罹急疾，餘驚而筮之，得《損》之《睽》。</p><p>斷曰：觀爻辭，已得明示，謂此病頗重，使名醫速施治療，可立愈也；若遷緩過期，雖名醫亦將束手，故曰“損其疾，使遄有喜，無咎”。不幸夜來，大雪紛飛，杜絕行道，朝來風雪益狂，餘冒雪赴品川，訪於氏之病室，醫師皆為大雪所阻，延期不到，果即日死去。亦天數也，可嘆可悼！</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>“十朋之龜”，元龜長一尺二寸，直二千一百六十，為大貝十朋；公龜九寸以上，直五百，為牡貝十朋；侯龜七寸以上，直三百，為公貝十朋；子龜五寸以上，直百，為小貝十朋——見《漢書》。《坤》數十，又偶為朋，故有“十朋”之象。龜者靈物，能前知吉凶，為卜質吉凶之具。此爻柔順得中，誠孚於下，故人獻其誠。“或益之十朋之龜”，“或”者，不知其所從來之辭，意外之益，君子疑焉，故問之於卜筮。理數已定，十朋之元龜，不能違，其吉可知，故曰“十朋之龜，弗克違，元吉”。《象傳》以“自上保祐也”釋之，“上祐”者，“自天祐之”也。以爻象言，“上”指上爻，謂上能輔祐六五之君也。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：運途全盛，可得意外寵遇。</p><p>○　問戰徵：軍事先卜，其兆大吉。</p><p>○　問營商：財運之來，雖辭不去。</p><p>○　問功名：“自天祐之，吉無不利”。</p><p>○　問家宅：家業興隆，不卜可知。</p><p>○　問婚姻：天作之合，吉。</p><p>○　問疾病：病癒之後，且可得財，吉。</p><p>○　問六甲：生男。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>東京豪商某家甲幹某來，曰僕受本店之命，擔任大藏省用務，率數百人以從事。近聞明年大藏省將有改革，此事擬廢，則僕所管數百人，一時皆失其業，實所不忍。今轉謀於某會社，欲授此等人以相當之業，請佔其可否？筮得《損》之《中孚》。</p><p>斷曰：此爻以陽居五，位得中正，可知足下秉心正直，當久任其事，不必轉而他往也。“十”朋之龜”者，謂將來有意外之幸福也。今者大藏省有改革之議，其中或損或益，足下別有擔任之務，此數百人，因之得福，亦未可知。就爻位推之，明年當上爻，爻辭曰“弗損益之，無咎，貞吉，利有攸往”，明年無所損益，且貞吉有利，此事務或不復擬廢，亦未定也。總之足下與此數百人，皆得無咎且吉，不必懷憂。某大喜，後果如此佔。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>此爻居《損》之極，不可復損也，曰“弗損益之”，其辭與二同，其義與二別。上與三應，三處當《損》之位，人或疑《損》三以《益》上，三之《損》實為上之《益》也，故特示之曰“弗損益之”，以明三雖有損，而於上則無所損益焉。無損則事皆平均而“無咎”，理得安詳而“貞吉”。“利有攸往”，即《彖傳》所稱“與時偕行”之義，上為《艮》之極，極則變，故不為止而為往也。上互《坤》，《坤》為臣，《艮》為家，《艮》動而變《坤》，“得臣無家”之象。弗損下以益上，是王者以天下為家，臣下化之，亦皆國而忘家，故曰“得臣無家”。《象傳》以“大得志”釋之，謂王者以不損益為《益》，潛移默化，不見其跡，志量之所及甚大，故曰“大得志也”。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：目下絕無窒礙，所往皆利，大吉。</p><p>○　問戰徵：軍隊不須添減，率此以往，攻克戰勝，無往不利，可“大得志也”。</p><p>○　問營商：貨價無甚上落，往售皆可獲利，大吉。</p><p>○　問功名：目下即可得志。</p><p>○　問家宅：此宅不必改造，自得吉利。</p><p>○　問疾病：當出外求醫，無咎。</p><p>○　問行人：在外大吉，一時未必歸家。</p><p>○　問六甲：生男。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治九年，長崎商人大浦阿啟與神代某來，曰：前自驛遞局，借與橫濱制鐵所，從事船舶修繕費用，後因得不償失，大被虧損，計將返納於驛遞局，或轉讓與他人。兩者未決，請佔其孰可？筮得《損》之《臨》。</p><p>斷曰：此爻為《損》之極，今後更無所損，不損則必有所益，故其辭曰“弗損益之，無咎，貞吉，利有攸往”也。二友信之，遂決計續承其業，翌年有西南之役，船舶繁多，大得利益雲。</p>',115)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
